LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $rows = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{where:main}} ORDER BY {{orderBy:main}} LIMIT {{limit}} OFFSET {{offset}};
LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $row = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($row.rows) == 0
  RETURN 404 { "ok": false, "error": "NOT_FOUND" };
END
RETURN 200 { "row": $row.rows[0] };

LET $s = QUERY SELECT capacity, booked FROM {{t:slot}} WHERE {{idColumn:slot}} = {{body.slot_id}} LIMIT 1;
IF LEN($s.rows) == 0
  RETURN 404 { "ok": false, "error": "NO_SLOT" };
END
IF $s.rows[0].booked >= $s.rows[0].capacity
  RETURN 409 { "ok": false, "error": "FULL" };
END
EXEC UPDATE {{t:slot}} SET booked = booked + 1 WHERE {{idColumn:slot}} = {{body.slot_id}} AND booked < capacity;
LET $ins = EXEC INSERT INTO {{t:main}} (service_id, slot_id, customer, phone) VALUES ({{body.service_id}}, {{body.slot_id}}, {{body.customer}}, {{body.phone}});
RETURN 201 { "ok": true, "id": $ins.insertId };

LET $b = QUERY SELECT slot_id, status FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($b.rows) == 0
  RETURN 404 { "ok": false, "error": "NO_BOOKING" };
END
IF $b.rows[0].status == 9
  RETURN 200 { "ok": true, "already": true };
END
EXEC UPDATE {{t:main}} SET status = 9 WHERE {{idColumn:main}} = {{id}};
EXEC UPDATE {{t:slot}} SET booked = booked - 1 WHERE {{idColumn:slot}} = $b.rows[0].slot_id AND booked > 0;
RETURN 200 { "ok": true };
